mapper.insert:
INSERT INTO recalculation_task (
    user_id, task_type, status, total_count, created_at, started_at
) VALUES (
    #{userId}, #{taskType}, COALESCE(#{status}, 'running'), COALESCE(#{totalCount}, 0),
    NOW(), NOW()
)

mapper.update:
UPDATE recalculation_task
SET status = 'running', started_at = NOW()
WHERE id = #{id}

UPDATE recalculation_task
SET status = 'succeeded', finished_at = NOW()
WHERE id = #{id}

UPDATE recalculation_task
SET status = 'failed', error_msg = #{errorMsg}, finished_at = NOW()
WHERE id = #{id}

UPDATE recalculation_task
SET success_count = #{successCount}, fail_count = #{failCount},
    failure_detail = #{failureDetail}
WHERE id = #{id}

UPDATE recalculation_task
SET ref_id = #{refId}
WHERE id = #{id}
